// @ts-check
// Some portions generated by Claude Code
const http = require('node:http');
const { hostFromServer, listenAddressForServer, serverBaseUrl } = require('./workbench-test-helpers');

/**
 * An RDF4J Server of a spec's own, in front of the real one at serverBaseUrl(): it passes requests on, except that it
 *  - with `user` and `password`, refuses (401) every request without those Basic credentials, but /protocol, which the
 *    Workbench reads without credentials before it accepts a server;
 *  - with `noRepositories`, lists no repositories.
 * It listens where the server reaches it (hostFromServer()). The Workbench only connects to a server its
 * accepted-server-prefixes setting allows: run.sh starts it allowing any port at that host. `requests` lists what the
 * stand-in was asked ("GET /rdf4j-server/protocol"), so a spec can tell a Workbench that did not accept it.
 *
 * @param {{ user?: string, password?: string, noRepositories?: boolean }} [options]
 */
async function startServerStandIn(options = {}) {
    const upstream = new URL(serverBaseUrl());
    const serverPath = upstream.pathname.replace(/\/+$/, '');
    const expected = options.user === undefined ? null
        : 'Basic ' + Buffer.from(`${options.user}:${options.password || ''}`, 'utf8').toString('base64');
    /** @type {string[]} */
    const requests = [];
    const server = http.createServer((request, response) => {
        const requestPath = String(request.url).split('?')[0];
        requests.push(`${request.method} ${requestPath}`);
        if (expected && requestPath !== `${serverPath}/protocol` && request.headers.authorization !== expected) {
            response.writeHead(401, { 'WWW-Authenticate': 'Basic realm="RDF4J stand-in"', 'Content-Type': 'text/plain' });
            response.end('Unauthorized');
            return;
        }
        if (options.noRepositories && request.method === 'GET' && requestPath === `${serverPath}/repositories`) {
            response.writeHead(200, { 'Content-Type': 'application/sparql-results+json' });
            response.end(JSON.stringify({ head: { vars: ['uri', 'id', 'title', 'readable', 'writable'] },
                results: { bindings: [] } }));
            return;
        }
        const headers = Object.assign({}, request.headers, { host: upstream.host });
        delete headers.authorization;
        const forwarded = http.request(new URL(String(request.url), upstream.origin), { method: request.method, headers },
            (answer) => {
                response.writeHead(answer.statusCode || 502, answer.headers);
                answer.pipe(response);
            });
        forwarded.on('error', (error) => response.destroy(error));
        request.pipe(forwarded);
    });
    await new Promise((resolve) => server.listen(0, listenAddressForServer(), () => resolve(undefined)));
    const address = server.address();
    const port = address && typeof address === 'object' ? address.port : 0;
    return {
        url: `http://${hostFromServer()}:${port}${serverPath}`,
        requests,
        /** Whether the Workbench accepted this server: it reads /protocol only of a server its setting allows. */
        accepted: () => requests.includes(`GET ${serverPath}/protocol`),
        close: () => new Promise((resolve) => {
            server.closeAllConnections();
            server.close(() => resolve(undefined));
        })
    };
}

/** What to tell the person running a spec whose Workbench does not accept the stand-in. */
function standInHint(url) {
    return `the Workbench did not connect to ${url}: start it with `
        + `-Dorg.eclipse.rdf4j.workbench.accepted-server-prefixes="/rdf4j-server http://${hostFromServer()}:" `
        + '(run.sh does)';
}

module.exports = { standInHint, startServerStandIn };
